'use strict';
// GK-017 r02 — checkout and order problem states. Local design prototype: no API, payment, analytics or messages.
// Loaded before app.js; app.js renders the shared header/footer and calls window.R02.pages / window.R02.bind.
// Every amount, date and deadline below is an EXAMPLE SERVER RESPONSE (FX). The page only displays them; it
// never adds up, halves or rounds money. Worked rounding examples are labelled as examples.

/* ---------- Shared time picker (r02 item: visible start–end times as a radio list, shared with GK-016) ---------- */
function timeOptions(list,selected,delivery,opts={}){
  const name=opts.name||'slot',gone=opts.gone||[];
  const rows=[...new Set([...list,...gone])].sort();
  if(!rows.length)return '';
  return rows.map(t=>{const off=gone.includes(t);const id=`${name}-${t.replace(/\D/g,'')}`;
    return `<label class="time-option${off?' is-off':''}" for="${id}"><input type="radio" id="${id}" name="${name}" value="${t}" ${t===selected&&!off?'checked':''} ${off?'disabled':''}><span><strong>${t}</strong><small>${off?'No longer available':delivery?'Requestable · subject to chef confirmation':'Available'}</small></span></label>`}).join('');
}
function timeLoading(){return `<p class="time-loading" role="status"><span class="r02-spin" aria-hidden="true"></span>Loading available times…</p><span class="time-skeleton" aria-hidden="true"></span><span class="time-skeleton" aria-hidden="true"></span>`}
function slotValue(form){return form.querySelector('input[name=slot]:checked')?.value||''}

(function(){
const q=new URLSearchParams(location.search);
// Screenshot mode (?shot=1): no focus move, no ticker, no footer (keeps the review images small).
if(q.has('shot'))document.documentElement.classList.add('r02-shot');
// Review shortcut: ?seed=pink puts Pink piping on 22 October in the demo bag (used for the checkout screenshot).
if(q.get('seed')==='pink'){try{sessionStorage.setItem('gk-poc-gk017r02-bag','["pink"]');sessionStorage.setItem('gk-poc-gk017r02-date','"2026-10-22"')}catch{}}
const FX={ref:'GK-1042',date:'2026-10-22',slot:'11:00–12:00',dateText:'Thu 22 October 2026',deadline:'11:00 (London time) on Sat 17 October',
  paid:9000,half:4500,newPrice:9500,newHalf:4750,delivery:12000,cakeHalf:4500,deliveryHalf:6000,deliveryTotal:21000,deliveryHalfTotal:10500,
  name:'Alex Morgan',email:'alex@example.com',postcode:'SE1 2AB',checked:'10:42',moveBy:'05:00 on Thu 22 October'};
const m=n=>money(n);
const DEADLINES={'11:00–12:00':'11:00 (London time) on Sat 17 October','12:00–13:00':'12:00 (London time) on Sat 17 October'}; // example server-provided deadlines per time
const arrow=()=>icon('arrow');
const pink=()=>product('pink'),choc=()=>product('chocolate');

/* ---------- Building blocks ---------- */
function para(lines){return lines.filter(Boolean).map(l=>`<p>${l}</p>`).join('')}
function notice(tone,lines,extra=''){return `<div class="notice ${tone}${extra}">${Array.isArray(lines)?`<div>${para(lines)}</div>`:lines}</div>`}
function status({tone='',title:t,lines=[],busy=false,live=true,after='',id='status-h'}){
  return `<section class="co-card r02-status" aria-labelledby="${id}"><div${live?' aria-live="polite"':''}><h2 class="co-h r02-focus" id="${id}" tabindex="-1">${busy?'<span class="r02-spin" aria-hidden="true"></span>':''}${t}</h2>${notice(tone,lines)}</div>${after}</section>`}
function next(titleText,items){return `<section class="co-card"><h2 class="co-h">${titleText}</h2><ol class="r02-next">${items.map(i=>`<li>${i}</li>`).join('')}</ol></section>`}
function track(steps,current,label='Refund progress'){return `<ol class="r02-track" aria-label="${label}">${steps.map((s,i)=>`<li class="${i<current?'done':i===current?'current':''}"${i===current?' aria-current="step"':''}><span>${s}</span>${i<current?'<span class="sr-only"> · done</span>':i===current?'<span class="sr-only"> · current step</span>':''}</li>`).join('')}</ol>`}
// Refund tracker for one card refund. State words follow the API refund block; past tense only for finished steps.
function refundTrack(state,label='Card refund progress'){const steps={requested:['Refund requested','Waiting to be sent to our payment provider','Return to your payment method'],pending:['Refund requested','Sent to our payment provider · waiting for them','Return to your payment method'],attention:['Refund requested','Needs a check by our team','Return to your payment method'],returned:['Refund requested','Sent to our payment provider','Returned to your payment method']}[state];return track(steps,{requested:0,pending:1,attention:1,returned:3}[state],label)}
// Per-collection refund lines: the chef's delivery refund always sits on its own line.
function refundLines(rows){return `<ul class="r02-split r02-refund-lines">${rows.map(([a,b,st])=>`<li><span>${a}${st?`<small>${st}</small>`:''}</span><span>${b}</span></li>`).join('')}</ul>`}
function actions(html){return `<div class="r02-actions">${html}</div>`}
function primary(label,attrs=''){return `<button type="button" class="primary co-pay r02-btn" ${attrs}><span>${label}</span> ${arrow()}</button>`}
function secondary(label,attrs=''){return `<button type="button" ${attrs}>${label}</button>`}
function link(label,href,cls='button'){return `<a class="${cls}" href="${href}">${label}</a>`}
function kept(n,h,text){return `<section class="co-card r02-kept"><h2 class="co-h"><span class="co-num" aria-hidden="true">${n}</span>${h}<span class="co-optional">Kept</span></h2><p>${text}</p></section>`}
function item(p,price,extra=''){return `<div class="sum-item">${image(p.id)}<div><strong>${p.name}</strong><span>${p.flavour} · ${p.size} · ${p.serves} servings${p.id==='chocolate'?' · ready-made':''}</span>${extra}</div><span class="sum-price">${price}</span></div>`}
function meta(rows){return `<dl class="sum-meta">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`}
function totals(rows){return rows.map(([a,b,cls])=>`<div class="totals${cls?' '+cls:''}"><span>${a}</span><span>${b}</span></div>`).join('')}

// Order details card shown beside every order-page state.
function orderSummary({requested=false,mode='collection',rows,note='',items}={}){
  const modeText={collection:'Collect · St Katharine Docks',courier:'Your courier collects',delivery:'GK delivery'}[mode];
  return `<aside class="co-summary" aria-labelledby="sum-title"><h2 id="sum-title">Order details</h2>${items||item(pink(),m(FX.paid))}${meta([
    [requested?'Requested date':'Date',FX.dateText+(requested?' (not confirmed yet)':'')],
    [requested?'Requested time':'Time',FX.slot+' · London time'+(requested?' (not confirmed yet)':'')],
    ['How you’ll get it',modeText],['Order reference',`<code>${FX.ref}</code>`]])}${totals(rows||[['Cakes',m(FX.paid)],['Paid',m(FX.paid),'total']])}${note?`<p class="small quiet">${note}</p>`:''}</aside>`}
function orderShell(cards,summary,heading='Your order'){
  return `<div class="wrap checkout-page r02-page">${title(heading,`Order ${FX.ref} · example`)}<div class="checkout-layout"><div class="r02-col">${cards}</div>${summary}</div></div>`}
// Checkout re-shown after a refusal at Continue: the problem first, the affected section open, the rest kept.
function checkoutShell(banner,sections,summary){
  return `<div class="wrap checkout-page r02-page">${title('Checkout','Guest checkout · nothing is charged in this preview.')}<p class="co-step-short">Step 2 of 4 · Checkout</p><div class="checkout-layout"><form id="r02-form" novalidate>${banner}${sections}</form>${summary}</div></div>`}
function problem(h,lines){return `<div class="r02-problem" role="alert"><h2 class="r02-focus" tabindex="-1">${h}</h2>${para(lines)}</div>`}
function confirmBox(note=''){return `<label class="check-line co-confirm r02-retick"><input type="checkbox" id="reviewed" name="reviewed"><span>I’ve checked the cake, allergens, date and the refund terms above. <a href="policies.html" target="_blank" rel="noopener">Full policies<span class="sr-only"> (opens in a new tab)</span> ↗</a></span></label>${note?`<p class="small r02-retick-note">${note}</p>`:''}<p id="reviewed-error" class="field-error" hidden>Tick to confirm you’ve checked your order.</p>`}
function terms(full,half,updated=false){return `<div class="co-policy${updated?' r02-updated':''}" id="refund-terms"><p class="co-label">Cancellation and refunds${updated?' · <span class="r02-badge">Updated</span>':''}</p><p>Cancel before <strong>${FX.deadline}</strong> for a full refund of <strong>${full}</strong>.</p><p>From then on, or if the cake isn’t collected, you get <strong>50% (${half})</strong>. If we have to cancel, you get 100% back.</p><p>Once you’ve paid, moving your date or time won’t change this deadline. After handover, contact the chef to request your 50% refund or if something is wrong.</p></div>`}
function allergen(p){return `<div class="co-allergen"><p class="co-label">${p.name} · allergens</p>${p.id==='chocolate'?'<p class="allergen-alert">Contains PEANUTS</p>':''}<p><strong>Contains: EGGS, MILK, CEREALS CONTAINING GLUTEN (WHEAT), SOYBEANS${p.id==='chocolate'?', PEANUTS':''}.</strong></p></div>`}
function checkoutSummary({items,rows,payLabel,disabled=false,note='In pounds (GBP). Decoration shown is included.'}){
  return `<aside class="co-summary" aria-labelledby="sum-title"><h2 id="sum-title">Your order</h2>${items}${meta([['Date',FX.dateText],['Time',FX.slot+' · London time'],['How you’ll get it','Collect · St Katharine Docks']])}${totals(rows)}<p class="small quiet">${note}</p><ul class="co-assure"><li>Your place on this date is held for 15 minutes while you pay. If your payment is still processing after that, we’ll wait for the result.</li><li>Your order is confirmed only when we receive the payment.</li><li>If a payment result is unclear, we check it for you. Please don’t pay twice.</li></ul><button type="submit" form="r02-form" class="primary co-pay" id="r02-pay" ${disabled?'disabled':''}><span id="pay-label">${payLabel}</span> ${arrow()}</button><p id="pay-status" class="sr-only" role="status"></p></aside>`}
function choices(name,list,selected=''){return `<fieldset class="r02-choices"><legend class="sr-only">Choose one</legend>${list.map(([v,h,s])=>`<label class="mode-card"><input type="radio" name="${name}" value="${v}" ${v===selected?'checked':''}><span><strong>${h}</strong><small>${s}</small></span></label>`).join('')}</fieldset>`}
function timeList(list,{selected='',delivery=false,gone=[],legend='Collection time · London time',name='slot',id='slot'}={}){
  return `<fieldset id="${id}" class="time-list" tabindex="-1" aria-describedby="${id}-status"><legend>${legend}</legend><div class="time-options">${timeOptions(list,selected,delivery,{name,gone})}</div></fieldset><p id="${id}-status" class="small quiet co-status" role="status"></p><p id="${id}-error" class="field-error" hidden>Choose a time.</p>`}

/* ---------- States ---------- */
// Each: group, label, api (what the API reports — review note only), variants [[id,label]], render(v).
const S={};
const def=(id,o)=>{S[id]=o};

def('price-changed',{group:'At Continue',label:'Price changed or total refreshed',api:'POST /checkouts → 409 PRICE_CHANGED (or QUOTE_EXPIRED after 24 h). The response carries a new reviewable quote; nothing is reserved or charged.',
 variants:[['price','Price changed'],['expired','Total older than 24 hours']],
 render:v=>{const exp=v==='expired';const price=exp?FX.paid:FX.newPrice,half=exp?FX.half:FX.newHalf;
  return checkoutShell(problem(exp?'We’ve refreshed your total':'The price has changed',[exp?'Your total was more than 24 hours old, so we’ve refreshed it. Nothing was charged.':'The price of a cake changed after your total was shown. Nothing was charged.','Please check the total and the refund amounts below, then tick the box again to continue.']),
  kept(1,'When and how',`${FX.dateText} · ${FX.slot} · Collect, St Katharine Docks`)+kept(2,'Your details',`${FX.name} · ${FX.email}`)+
  `<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">4</span>Before you pay</h2>${allergen(pink())}${terms(m(price),m(half),!exp)}${confirmBox(exp?'Your earlier tick was cleared because your total was refreshed.':'Your earlier tick was cleared because the total changed.')}</section>`+kept(5,'Payment','You’ll pay on our secure payment page.'),
  checkoutSummary({items:item(pink(),exp?m(price):`<span class="r02-was"><s><span class="sr-only">was </span>${m(FX.paid)}</s></span> <span class="sr-only">now </span>${m(price)}`),rows:[['Cakes',m(price)],['Collection','Free'],[exp?'To pay now':'New total · to pay now',m(price),'total']],payLabel:'Continue to secure payment · '+m(price)}))}});

def('terms-changed',{group:'At Continue',label:'Refund terms updated',api:'POST /checkouts → 409 POLICY_CHANGED. The page reloads GET /policies/current; consent must be given again to the new revision.',
 render:()=>checkoutShell(problem('Our refund terms were updated',['Our cancellation and refund terms changed while you were checking out. Nothing was charged.','Please read the current terms below and tick the box again. Your total hasn’t changed.']),
  kept(1,'When and how',`${FX.dateText} · ${FX.slot} · Collect, St Katharine Docks`)+kept(2,'Your details',`${FX.name} · ${FX.email}`)+
  `<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">4</span>Before you pay</h2>${allergen(pink())}${terms(m(FX.paid),m(FX.half),true)}<p class="small quiet co-statutory">Nothing in this cancellation and refund policy affects the customer’s statutory rights where a product is faulty, not as described or otherwise does not meet applicable legal requirements.</p>${confirmBox('Your earlier tick was for the previous terms, so it was cleared.')}</section>`,
  checkoutSummary({items:item(pink(),m(FX.paid)),rows:[['Cakes',m(FX.paid)],['Collection','Free'],['To pay now',m(FX.paid),'total']],payLabel:'Continue to secure payment · '+m(FX.paid)}))});

def('slot-taken',{group:'At Continue',label:'Time or date no longer available',api:'POST /checkouts → 409 SLOT_UNAVAILABLE with fresh schedule rows (time variant), or the date’s ordinary admissions closed (date variant). No replacement time is booked.',
 variants:[['time','Time taken'],['date','Date now full']],
 render:v=>{const date=v==='date';
  return checkoutShell(problem(date?'Thu 22 October is now fully booked':'That time is no longer available',date?['We can’t take new orders for Thu 22 October any more. Nothing was charged.','Please choose another date. Everything else you entered is kept.']:[`${FX.slot} on Thu 22 October can no longer be booked. Nothing was charged.`,'Please choose another time below. Everything else you entered is kept.']),
  `<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">1</span>When and how</h2><div class="co-date"><span>${icon('calendar')} <strong>${date?'<s>Thu, 22 October 2026</s> <span class="r02-badge">Full</span>':'Thu, 22 October 2026'}</strong> · London time</span><button class="text-link" type="button" data-date>Choose another date</button></div>${date?`<div class="notice"><div><p>No times can be booked on this date now. Choose another date, or <a href="contact.html">contact the chef</a> if this date matters.</p></div></div>`:timeList(['12:00–13:00'],{gone:['11:00–12:00']})}</section>`+
  kept(2,'Your details',`${FX.name} · ${FX.email}`)+(date?kept(4,'Before you pay','Shown again with your new refund deadline once you’ve chosen a date and time.'):`<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">4</span>Before you pay</h2>${allergen(pink())}<div class="co-policy" id="refund-terms"><p class="co-label">Cancellation and refunds</p><p>Choose a time to see your exact cancellation deadline.</p></div>${confirmBox('Your earlier tick was cleared: your refund deadline follows the new time.')}</section>`)+kept(5,'Payment','You’ll pay on our secure payment page.'),
  checkoutSummary({items:item(pink(),m(FX.paid)),rows:[['Cakes',m(FX.paid)],['Collection','Free'],['To pay now',m(FX.paid),'total']],payLabel:date?'Choose another date first':'Continue to secure payment · '+m(FX.paid),disabled:date}).replace(`<div><dt>Time</dt><dd>${FX.slot} · London time</dd></div>`,`<div><dt>Time</dt><dd id="sum-time">Choose a time</dd></div>`))}});

def('item-gone',{group:'At Continue',label:'Cake no longer available',api:'POST /checkouts → 409 ITEM_UNAVAILABLE (finite ready-made stock). No partial reservation. Removing the cake requests a new quote.',
 variants:[['gone','Cake gone'],['removed','After removing it']],
 render:v=>{const removed=v==='removed';
  return checkoutShell(removed?problem('Chocolate swirl removed · new total',['Your order now has Pink piping only. This is the new total from our system. Please check it and tick the box again.']):problem('Chocolate swirl is no longer available',['This ready-made cake has just been sold. Nothing was charged.','Remove it to continue with Pink piping, or go back to your bag to choose again. We won’t swap it for another cake.']),
  (removed?'':`<section class="co-card"><h2 class="co-h">Your cakes</h2>${item(choc(),'<span class="r02-badge">Sold</span>','<span class="r02-gone">No longer available</span>')}${item(pink(),m(FX.paid))}${actions(primary('Remove Chocolate swirl and update the total','data-go="item-gone" data-v="removed"')+link('Back to your bag','bag.html'))}</section>`)+
  kept(1,'When and how',`${FX.dateText} · ${FX.slot} · Collect, St Katharine Docks`)+kept(2,'Your details',`${FX.name} · ${FX.email}`)+
  (removed?`<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">4</span>Before you pay</h2>${allergen(pink())}${terms(m(FX.paid),m(FX.half),true)}${confirmBox('Your earlier tick was cleared because your order changed.')}</section>`:kept(4,'Before you pay','Shown again for the remaining cakes once the total is updated.')),
  checkoutSummary({items:removed?item(pink(),m(FX.paid)):item(choc(),'—','<span class="r02-gone">No longer available</span>')+item(pink(),m(FX.paid)),rows:removed?[['Cakes',m(FX.paid)],['Collection','Free'],['New total · to pay now',m(FX.paid),'total']]:[['Cakes','Waiting for a new total'],['To pay now','—','total']],payLabel:removed?'Continue to secure payment · '+m(FX.paid):'Remove the sold cake first',disabled:!removed}))}});

def('other-refusals',{group:'At Continue',label:'Other refusals (lead time, code, payment under way)',api:'409 LEAD_TIME, CODE_USED_UP, PAYMENT_IN_PROGRESS — wording reused from the built checkout (ui/src/lib/checkout/messages.ts).',
 render:()=>`<div class="wrap checkout-page r02-page">${title('Other refusals','How the remaining Continue problems read. Each replaces the banner at the top of the checkout.')}<div class="r02-grid">${[
  ['LEAD_TIME · at Continue','This date is now too soon','This time is now too soon: we need at least 8 days (192 hours) from payment to make your cake. Nothing was charged. Please choose a later date.',secondary('Choose a later date','data-date')],
  ['LEAD_TIME · order page','Too late to pay for this date','It’s now too late to pay for this date: we need at least 8 days (192 hours) from payment to make your cake. Nothing was charged. Please start a new order with a later date.',secondary('Start a new order','data-restart')],
  ['CODE_USED_UP','Your discount code was removed','That discount code has just been used up, so we’ve removed it. Please review your new total and tick the box again.',secondary('Review the new total','data-go="price-changed"')],
  ['PAYMENT_IN_PROGRESS','A payment is already under way','A payment for this order is already in progress. Please don’t pay again: check your order for the result.',link('View your order','recovery.html?state=still-checking')]
 ].map(([tag,h,t,b])=>`<section class="co-card"><p class="co-label">${tag}</p><div class="r02-problem"><h2>${h}</h2><p>${t}</p></div>${actions(b)}</section>`).join('')}</div></div>`});

def('still-checking',{group:'After the payment page',label:'Still checking payment',api:'Order awaiting_payment, payment pending/unknown, after ?payment=returned. Polls from 3 s backing off to 30 s; stops after 5 minutes with Refresh.',
 variants:[['polling','Checking'],['stopped','Stopped after 5 min'],['open','Payment page still open']],
 render:v=>orderShell(status({title:'Still checking payment; do not pay again',busy:v!=='stopped',lines:v==='open'?['Please don’t pay again. We’ll update this page when we know the result.','Your place on Thu 22 October is held while you pay.','Your secure payment page is still open. If you left it before paying, you can go back to it: it’s the same payment, so you won’t be charged twice. This link disappears once the payment page closes.']:['Please don’t pay again. We’ll update this page when we know the result.','Your place on Thu 22 October stays held while we wait for the result, even after the 15 minutes.'],
   after:(v==='stopped'?`<p class="small" role="status">We’re still waiting for a result. Please don’t pay again. Refresh to check, or come back later.</p>${actions(secondary('Refresh status','data-go="still-checking" data-v="polling"')+link('Contact us','contact.html','text-link'))}`:`<p class="small r02-poll" id="r02-poll" data-poll>Checked at ${FX.checked} · this page updates by itself.</p>`)+(v==='open'?actions(secondary('Back to the secure payment page','data-go="still-checking" data-v="polling"')):'')})+
  next('What happens next',['Our payment provider tells us the result. Some payment methods take longer than others.','If the payment went through, this page shows your confirmed order.','If it didn’t go through, this page says so. Nothing is charged, and you can try again while your place is still held.','If the result stays unclear, a member of our team checks it for you.']),
  orderSummary({rows:[['Cakes',m(FX.paid)],['Total',m(FX.paid),'total']],note:'Not paid yet as far as we know. The total is shown in pounds (GBP).'}))});

def('unknown-result',{group:'After the payment page',label:'Result unclear · a person is checking',api:'Payment unknown (provider outage, missing provider ID or expiry failure). Chef queue owns follow-up; place and code stay reserved; no new payment can start.',
 render:()=>orderShell(status({tone:'warning',title:'We’re checking your payment',lines:['We couldn’t get a clear result from our payment provider, so a member of our team is checking it for you.','<strong>Please don’t pay again.</strong> Your place on Thu 22 October and any discount code stay with this order while we check.','If the payment went through, we’ll confirm your order, or, if we can’t make your cake for that date, return everything you paid. If it didn’t, nothing was charged.'],after:actions(link('Contact us','contact.html'))+`<p class="small quiet">Quote order reference <code>${FX.ref}</code>. This page updates by itself.</p>`})+
  next('What happens next',['We check the payment with our payment provider. You don’t need to do anything.','This page then shows the result: confirmed, or not paid.','If we need anything from you, we’ll contact you at '+FX.email+'.']),orderSummary({rows:[['Cakes',m(FX.paid)],['Total',m(FX.paid),'total']],note:'Payment result being checked.'}))});

def('confirming',{group:'After the payment page',label:'Payment received · confirming',api:'Lifecycle confirmation_pending (or payment succeeded while the order is still awaiting_payment). Polls until confirmed.',
 render:()=>orderShell(status({title:'Payment received — confirming your order',busy:true,lines:['We’ve received your payment and are confirming your order. This usually takes a few seconds.','Please don’t pay again.'],after:`<p class="small r02-poll" data-poll>This page updates by itself.</p>`}),orderSummary({rows:[['Cakes',m(FX.paid)],['Paid',m(FX.paid),'total']]}))});

def('hold-released',{group:'After the payment page',label:'Time ran out · place released',api:'Lifecycle cancelled, cancel_reason payment_not_completed — only after the provider proves the session unpaid. A new order needs a new quote.',
 render:()=>orderShell(status({tone:'error',title:'Your place was released',lines:['The payment wasn’t completed, so this order was cancelled and your place released. No payment was taken.','You can start a new order with the same cakes. We’ll check the price and times again, so the total or available times may differ.'],after:actions(primary('Start a new order with the same cakes','data-restart')+link('Contact us','contact.html','text-link'))+`<p class="small quiet">Paid on another device or tab? Don’t pay again: contact us with order reference <code>${FX.ref}</code>.</p>`}),
  orderSummary({rows:[['Cakes',m(FX.paid)],['Total (not paid)',m(FX.paid),'total']],note:'Cancelled before payment. Nothing to refund.'}))});

def('late-payment',{group:'After the payment page',label:'Paid after the preparation time',api:'Lifecycle paid_awaiting_agreement (Q2). Payment succeeded; no promise shown; production waits. Chef records feasibility; the customer must agree explicitly; otherwise full return. Silence is not agreement.',
 variants:[['waiting','Waiting for the chef'],['offer','Chef offers a date'],['agreed','You agreed']],
 render:v=>{if(v==='agreed')return orderShell(status({tone:'success',title:'Your order is confirmed',lines:['Thank you. You agreed to Thu 22 October, 11:00–12:00, and we’ve received your payment.']})+`<section class="co-card"><h2 class="co-h">Cancellation and refunds</h2><p class="small">Cancel before ${FX.deadline} for a full refund of what you paid. From then on, or if the cake isn’t collected, 50% of what you paid, rounded in your favour; 100% if we have to cancel.</p></section>`,orderSummary({}));
  const offer=v==='offer';
  return orderShell(status({tone:'warning',title:offer?'The chef can make your cake':'Payment received',lines:offer?['Your payment arrived after the time we need to prepare your cake, so we checked with the chef first.','The chef can make your cake for <strong>Thu 22 October, 11:00–12:00</strong>. Do you agree to this date and time?','If you’d rather not, you get everything you paid back: <strong>'+m(FX.paid)+'</strong>. Nothing is made until you decide.']:['Your payment arrived after the time we need to prepare your cake for this date. The chef will contact you about the date.','Thu 22 October is your requested date. It isn’t confirmed yet, and we won’t change it without your agreement.','If you and the chef can’t agree a date, you get everything you paid back: <strong>'+m(FX.paid)+'</strong>.','Please don’t pay again.'],
   after:offer?actions(primary('Yes, confirm this date','data-go="late-payment" data-v="agreed"')+secondary('No, refund everything · '+m(FX.paid),'data-go="refund" data-v="requested-full"')):actions(link('Contact the chef','contact.html'))}) +
  (offer?'':next('What happens next',['The chef checks whether your cake can still be made in time.','The chef contacts you. You decide: we never confirm or move your date unless you agree.','If you agree, your order is confirmed. If you don’t, or the chef can’t make it, you get '+m(FX.paid)+' back in full.'])),
  orderSummary({requested:true,note:'If the date can’t be agreed, you get everything you paid back.'}))}});

def('late-on-cancelled',{group:'After the payment page',label:'Paid after the order was cancelled',api:'Order cancelled; a genuine payment succeeded later → reconciliation: funds kept, dispatch frozen, full-return goal. refund.state requested → pending → returned (needs_attention when blocked). Never “returned” before the API says so.',
 variants:[['requested','Requested'],['pending','Pending'],['returned','Returned'],['attention','Needs a check']],
 render:v=>{  const line={requested:`Refund of ${m(FX.paid)} requested. We’ll update this page as it progresses.`,pending:`Refund of ${m(FX.paid)} pending: we’ve asked our payment provider to return it. We’ll update this page when it has been returned.`,returned:`Refund of ${m(FX.paid)} returned to your payment method. Your bank may take a few days to show it.`,attention:`Your refund of ${m(FX.paid)} needs a check by our team before we can send it. We’ll contact you if we need anything.`}[v];
  return orderShell(status({tone:v==='returned'?'success':'warning',title:'Payment received after this order was cancelled',lines:['This order had already been cancelled because the payment wasn’t completed in time, and then your payment of <strong>'+m(FX.paid)+'</strong> arrived. We’ve kept it safe and are returning all of it to you.',line,'Please don’t pay again. Your cake won’t be made for this order.'],
   after:refundTrack(v)+actions(link('Start a new order','bag.html')+link('Contact us','contact.html','text-link'))}),
  orderSummary({rows:[['Cakes',m(FX.paid)],['Paid (after cancellation)',m(FX.paid),'total'],['Refund · '+{requested:'requested',pending:'pending',returned:'returned',attention:'needs a check'}[v],m(FX.paid)]],note:'Full refund of everything paid. Refund amounts come from our system.'}))}});

def('cancel',{group:'Cancellation and refunds',label:'Cancellation preview and 120-hour deadline',api:'Order confirmed. Preview from the server (amount, deadline, policy). At the deadline the preview refreshes and must be confirmed again; a cancel sent with the old amount is refused with the new one.',
 variants:[['before','Before the deadline'],['boundary','Deadline passed while open'],['after','After the deadline'],['delivery','After · with GK delivery']],
 render:v=>{const del=v==='delivery',after=v==='after'||del,boundary=v==='boundary';
  const amount=del?FX.deliveryHalfTotal:after||boundary?FX.half:FX.paid;
  const panel=`<section class="co-card r02-cancel" aria-labelledby="cancel-h"><h2 class="co-h r02-focus" id="cancel-h" tabindex="-1">Cancel your order?</h2>${boundary?`<div class="r02-problem" role="alert"><h3>The full-refund deadline has just passed</h3><p>It was ${FX.deadline}. Your refund is now <strong>${m(FX.half)}</strong> (50% of what you paid, rounded in your favour). Please confirm again if you still want to cancel.</p></div>`:''}
   <div class="r02-refund-box"><p class="co-label">${after||boundary?'Cancelling after the full-refund deadline':'Cancelling before '+FX.deadline}</p><p class="r02-amount">You get back <strong>${m(amount)}</strong></p><p>${after||boundary?'50% of what you paid'+(del?' (cakes and delivery)':'')+', rounded in your favour.':'Everything you paid: a full refund.'}</p>${del?`<ul class="r02-split"><li><span>Cakes · back to your payment method</span><span>${m(FX.cakeHalf)}</span></li><li><span>Delivery · sent separately by the chef</span><span>${m(FX.deliveryHalf)}</span></li></ul>`:''}${v==='before'?`<p class="small">Full refund until ${FX.deadline} · <strong>3 days 4 hours</strong> left (checked at ${FX.checked}). If the deadline passes while this is open, we’ll show the new amount and ask you to confirm again.</p>`:''}</div>
   ${after&&!del?`<div class="r02-example"><p class="co-label">Example · how rounding works</p><p>If you had paid £85.85, 50% would be £42.925, so you’d get <strong>£42.93</strong>: half pennies are rounded in your favour.</p></div>`:''}
   <p class="small">If we have to cancel, you always get 100% back. The refund goes to the payment method you used, and this page shows its progress.</p>
   ${actions(primary(`Cancel order · refund ${m(amount)}`,`data-go="refund" data-v="${del?'requested-delivery':after||boundary?'requested-half':'requested'}"`)+secondary('Keep my order','data-keep'))}</section>`;
  return orderShell(status({tone:'success',title:'Your order is confirmed',live:false,id:'conf-h',lines:['We’ve received your payment and your order is confirmed.']})+panel,
   orderSummary({mode:del?'delivery':'collection',rows:del?[['Cakes',m(FX.paid)],['GK delivery (paid separately)',m(FX.delivery)],['Paid',m(FX.deliveryTotal),'total']]:undefined,note:'Refund terms were agreed at payment and don’t change if you move the time.'}))}});

def('refund',{group:'Cancellation and refunds',label:'Refund progress',api:'Order cancelled with refund block: requested, pending, partly_returned (target_minor vs succeeded_minor), returned, needs_attention. The amount always matches the confirmed cancellation. Delivery money is returned by the chef as its own step.',
 variants:[['requested','Requested · £90 (before deadline)'],['requested-half','Requested · £45 (after deadline)'],['requested-delivery','Requested · £105 (with GK delivery)'],['partly','Partly returned'],['pending','Pending'],['returned','Returned'],['attention','Needs a check'],['chef','We cancelled'],['requested-full','Full refund · date not agreed'],['q5','Full refund · we couldn’t deliver'],['q5-paid','Full refund · delivery was paid']],
 render:v=>{const del=['requested-delivery','partly','q5-paid'].includes(v);
  const target={'requested-half':FX.half,'requested-delivery':FX.deliveryHalfTotal,partly:FX.deliveryHalfTotal,'q5-paid':FX.deliveryTotal}[v]||FX.paid;
  const cake={'requested-half':FX.half,'requested-delivery':FX.cakeHalf,partly:FX.cakeHalf,'q5-paid':FX.paid}[v]||FX.paid;
  const delAmt=v==='q5-paid'?FX.delivery:FX.deliveryHalf;
  const st={pending:'pending',returned:'returned',attention:'attention',partly:'returned'}[v]||'requested';
  const head={chef:'We had to cancel your order','requested-full':'Your order is cancelled · full refund',q5:'Your order is cancelled · full refund','q5-paid':'Your order is cancelled · full refund'}[v]||'Your order is cancelled';
  const why={'requested':'You cancelled before the full-refund deadline, so you get everything you paid back.','requested-half':'You cancelled after the full-refund deadline, so you get 50% of what you paid, rounded in your favour.','requested-delivery':'You cancelled after the full-refund deadline, so you get 50% of everything you paid, cakes and delivery, rounded in your favour.',chef:'We’re sorry: we can’t make your cake for this date, so we’ve cancelled your order. You get 100% of what you paid back.','requested-full':'You chose not to go ahead with the date, so you get everything you paid back.',q5:'We couldn’t deliver your cake and you chose a full refund, so you get everything you paid back.','q5-paid':'We couldn’t deliver your cake and you chose a full refund: everything you paid, cakes and delivery, comes back.'}[v];
  const line={requested:`Refund of ${m(target)} requested. We’ll update this page as it progresses.`,pending:`Refund of ${m(target)} pending: we’ve asked our payment provider to return it. We’ll update this page when it has been returned.`,returned:`Refund of ${m(target)} returned to your payment method. Your bank may take a few days to show it.`,attention:`Your refund of ${m(target)} needs a check by our team before we can send it. We’ll contact you if we need anything.`}[st];
  const lines=v==='partly'?[`${m(FX.cakeHalf)} of ${m(target)} returned so far; the rest is still pending.`,'The chef sends the delivery part separately.']:[why,line].filter(Boolean);
  const split=del?refundLines([['Cakes · to your payment method',m(cake),v==='partly'?'Returned':'Requested'],['Delivery · sent separately by the chef',m(delAmt),'Waiting for the chef']]):'';
  return orderShell(status({tone:st==='returned'&&v!=='partly'?'success':st==='attention'?'warning':'',title:head,lines,after:split+refundTrack(st,del?'Cake refund progress':'Refund progress')+actions(link('Contact us','contact.html','text-link'))}),
   orderSummary({mode:del?'delivery':'collection',rows:del?[['Cakes',m(FX.paid)],['GK delivery',m(FX.delivery)],['Paid',m(FX.deliveryTotal),'total'],['Refund due',m(target)],['Returned so far',v==='partly'?m(FX.cakeHalf):'£0']]:[['Cakes',m(FX.paid)],['Paid',m(FX.paid),'total'],['Refund due',m(target)],['Returned so far',st==='returned'?m(target):'£0']],note:'“Returned” appears only when our payment provider confirms it.'}))}});

def('delivery-impossible',{group:'GK delivery',label:'We can’t deliver after payment (Q5)',api:'Chef records delivery infeasible after the cake is paid. Customer chooses collection, own courier or full refund of everything paid (Creator Q5, 2026-11-04). A paid delivery is returned in full (GK-caused unperformed delivery). Refund deadline and preparation anchor unchanged.',
 variants:[['choose','Choose'],['delivery-paid','Choose · delivery already paid'],['collection','Collection chosen'],['courier','Own courier chosen'],['collection-paid','Collection chosen · delivery refund'],['courier-paid','Own courier chosen · delivery refund']],
 render:v=>{const paidDel=v.endsWith('paid');
  if(['collection','courier','collection-paid','courier-paid'].includes(v)){const cour=v.startsWith('courier');
   return orderShell(status({tone:'success',title:cour?'Your courier will collect your cake':'You’ll collect your cake',lines:[cour?'Thank you. Your courier collects from St Katharine Docks on Thu 22 October, 12:00–13:00 (London time). You book and pay the courier; responsibility passes to them at handover.':'Thank you. Your order is now for collection from St Katharine Docks on Thu 22 October, 12:00–13:00 (London time).',paidDel?`Your delivery payment of <strong>${m(FX.delivery)}</strong> is being returned in full. This page shows its progress.`:'','Your refund deadline hasn’t changed: '+FX.deadline+'.']}),
    orderSummary({mode:cour?'courier':'collection',rows:paidDel?[['Cakes',m(FX.paid)],['GK delivery',m(FX.delivery)],['Paid',m(FX.deliveryTotal),'total'],['Delivery refund · requested',m(FX.delivery)]]:undefined}).replace('11:00–12:00','12:00–13:00'))}
  const all=paidDel?FX.deliveryTotal:FX.paid;
  return orderShell(status({tone:'warning',title:'We can’t deliver your cake',lines:['We’re sorry: the chef can’t deliver to '+FX.postcode+' for Thu 22 October. Your cake is paid and still booked for that day.',paidDel?`Your delivery payment of <strong>${m(FX.delivery)}</strong> will be returned in full, whatever you choose.`:'',`Please choose what you’d like below. Nothing changes until you confirm.`]})+
  `<section class="co-card"><h2 class="co-h">What would you like to do?</h2><form id="r02-choose" data-paid="${paidDel?'1':''}">${choices('alt',[['collection','Collect it · free','St Katharine Docks, London, on Thu 22 October.'],['courier','Send your own courier','You book and pay your courier to collect on Thu 22 October. Responsibility passes to them at handover.'],['refund','Full refund · '+m(all),'Everything you paid back'+(paidDel?', cake and delivery':'')+'. Your order is cancelled.']])}
   <div id="alt-time" hidden>${timeList(['11:00–12:00','12:00–13:00'],{legend:'Collection time on Thu 22 October · London time',name:'alttime',id:'alttime'})}</div>
   <p class="small">Your refund deadline stays ${FX.deadline}.</p><p id="alt-error" class="field-error" hidden>Choose one option.</p>${actions(primary('Confirm my choice','data-alt'))}</form></section>`,
  orderSummary({mode:'delivery',rows:paidDel?[['Cakes',m(FX.paid)],['GK delivery',m(FX.delivery)],['Paid',m(FX.deliveryTotal),'total']]:[['Cakes',m(FX.paid)],['Paid',m(FX.paid),'total'],['GK delivery','Not paid']],note:'Delivery was a request until the chef confirmed it.'}))}});

def('delivery-unpaid',{group:'GK delivery',label:'Delivery quote not paid yet',api:'Separate delivery collection awaiting payment on the same order; cannot be dispatched unpaid; its payment never moves the cake’s deadline. Alternatives per Q5.',
 variants:[['quote','Quote waiting'],['checking','Delivery payment being checked']],
 render:v=>{const chk=v==='checking';
  return orderShell(status({tone:chk?'':'warning',busy:chk,title:chk?'Still checking delivery payment; do not pay again':'Your delivery quote is waiting for payment',lines:chk?['Please don’t pay again. We’ll update this page when we know the result.','Your cake order is confirmed and isn’t affected.']:[`The chef can deliver to ${FX.postcode} on Thu 22 October, 11:00–12:00 for <strong>${m(FX.delivery)}</strong>.`,'Your cake is paid and confirmed. We can deliver only once the delivery is paid.'],
   after:chk?`<p class="small r02-poll" data-poll>This page updates by itself.</p>`:actions(primary('Pay for delivery · '+m(FX.delivery),'data-go="delivery-unpaid" data-v="checking"'))})+
   (chk?'':`<section class="co-card"><h2 class="co-h">Don’t want delivery?</h2><p class="small">You can choose instead. Nothing changes until you confirm.</p><form id="r02-choose">${choices('alt',[['collection','Collect it · free','St Katharine Docks, on Thu 22 October.'],['courier','Send your own courier','You book and pay your courier. Responsibility passes to them at handover.'],['refund','Full refund · '+m(FX.paid),'Everything you paid back. Your order is cancelled.']])}<div id="alt-time" hidden>${timeList(['11:00–12:00','12:00–13:00'],{legend:'Collection time on Thu 22 October · London time',name:'alttime',id:'alttime'})}</div><p id="alt-error" class="field-error" hidden>Choose one option.</p>${actions(secondary('Confirm my choice','data-alt'))}</form></section>`),
   orderSummary({mode:'delivery',rows:[['Cakes',m(FX.paid)],['Paid',m(FX.paid),'total'],['GK delivery · quoted, not paid',m(FX.delivery)]],note:'Delivery is paid separately. Your refund deadline doesn’t move when you pay for delivery.'}))}});

def('free',{group:'Free order',label:'Free order (£0) confirmation',api:'Quote total_minor 0 → POST /orders/{id}/free-confirmation (no payment page, no payment row). free_confirmation processing/confirmed/refused(order_changed | holds_released | window_closed).',
 variants:[['checkout','Checkout'],['confirm','Confirm'],['confirming','Confirming'],['changed','Refused · order changed'],['released','Refused · place released'],['closed','Refused · time passed']],
 render:v=>{if(v==='checkout')return checkoutShell('',kept(1,'When and how',`${FX.dateText} · ${FX.slot} · Collect, St Katharine Docks`)+kept(2,'Your details',`${FX.name} · ${FX.email}`)+kept(3,'Discount code','GIFT100 · 100% off cakes · example code')+`<section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">4</span>Before you pay</h2>${allergen(pink())}<div class="co-policy"><p class="co-label">Cancellation</p><p>This order is free, so there’s nothing to refund if it’s cancelled. Please cancel before ${FX.deadline} if you can’t use your date.</p></div>${confirmBox()}</section><section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">5</span>Payment</h2><p class="co-lead">Nothing to pay: you’ll confirm your order on the next screen. No payment page opens.</p></section>`,
   checkoutSummary({items:item(pink(),m(FX.paid)),rows:[['Cakes',m(FX.paid)],['Discount · GIFT100','−'+m(FX.paid)],['Collection','Free'],['To pay now','£0','total']],payLabel:'Continue · confirm your free order',note:'In pounds (GBP). Totals from our system.'}));
  const L={confirm:{t:'Confirm your order',l:['Your order costs nothing to pay. Confirm it to book your date.','Your place on Thu 22 October is held for 15 minutes while you confirm.'],a:primary('Confirm order','data-go="free" data-v="confirming"')},
   confirming:{t:'Confirming your order',busy:true,l:['We’re confirming your free order. This usually takes a few seconds.']},
   changed:{tone:'warning',t:'We couldn’t confirm your order yet',l:['Something changed while we were confirming it. You can try again; if it still can’t be confirmed, please start a new order.'],a:primary('Try again','data-go="free" data-v="confirming"')},
   released:{tone:'error',t:'We couldn’t confirm your order',l:['Your place on this date was released, so this order can’t be confirmed. Please start a new order.'],a:primary('Start a new order','data-restart')},
   closed:{tone:'error',t:'We couldn’t confirm your order',l:['The time to confirm this order has passed, so it can’t be confirmed now. Please start a new order.'],a:primary('Start a new order','data-restart')}}[v];
  return orderShell(status({tone:L.tone||'',busy:L.busy,title:L.t,lines:L.l,after:(L.a?actions(L.a):'')+(L.busy?`<p class="small r02-poll" data-poll>This page updates by itself.</p>`:'')}),orderSummary({rows:[['Cakes',m(FX.paid)],['Discount · GIFT100','−'+m(FX.paid)],['Total','£0','total']],note:'Free order: no payment is taken. With GK delivery, the delivery quote is still paid separately.'}))}});

// Order timeline: money and the cake's progress side by side; each lane moves on its own.
function lanes(money,cake){const lane=(h,rows)=>`<section class="r02-lane" aria-labelledby="lane-${h.replace(/\W/g,'')}"><h3 id="lane-${h.replace(/\W/g,'')}">${h}</h3><ol class="r02-steps">${rows.map(([t,d,st])=>`<li class="${st||''}"${st==='current'?' aria-current="step"':''}><strong>${t}</strong>${d?`<span>${d}</span>`:''}<span class="sr-only">${{done:' · done',current:' · now',problem:' · problem'}[st]||' · not yet'}</span></li>`).join('')}</ol></section>`;
  return `<section class="co-card"><h2 class="co-h">Order timeline</h2><div class="r02-lanes">${lane('Money',money)}${lane('Your cake',cake)}</div></section>`}
def('timeline',{group:'Order timeline',label:'Money and cake progress side by side',api:'Order view with independent lifecycle (confirmed → in_production → ready → completed / cancelled), payment and refund block, and fulfilment (awaiting_handover, out_for_delivery, completed, exception). Post-handover refunds never rewind fulfilled history.',
 variants:[['production','Confirmed · being made'],['delivery','GK delivery · being made'],['cancel-production','Cancel while being made'],['no-show','Not collected (no-show)'],['completed','Collected · ask the chef'],['completed-refund','Collected · refund via the chef'],['delivery-failed','Delivery failed on the day']],
 render:v=>{const paidRow=['Paid '+m(FX.paid),'Tue 6 October, 14:05','done'],confirmed=['Order confirmed','Tue 6 October','done'],made=['Made by the chef','Started Thu 8 October','done'],ready=['Ready for collection','Thu 22 October','done'];
  const refundWindow=['Full refund until 11:00 on Sat 17 October','From then on 50% if you cancel; 100% if we cancel',''];
  if(v==='production'||v==='cancel-production'){const cancel=v==='cancel-production';
   return orderShell(status({tone:'success',title:'Your cake is being made',live:false,id:'conf-h',lines:['We’ve received your payment and your order is confirmed. The chef has started making your cake.']})+
    lanes([paidRow,refundWindow],[confirmed,['Being made','The chef started on Thu 8 October','current'],['Ready for collection','We send the exact collection address about 48 hours before',''],['Collected','Thu 22 October, 11:00–12:00 · St Katharine Docks','']])+
    (cancel?`<section class="co-card r02-cancel" aria-labelledby="cancel-h"><h2 class="co-h r02-focus" id="cancel-h" tabindex="-1">Cancel your order?</h2><div class="r02-refund-box"><p class="co-label">Cancelling before ${FX.deadline}</p><p class="r02-amount">You get back <strong>${m(FX.paid)}</strong></p><p>Everything you paid. Your cake already being made doesn’t reduce your refund.</p><p class="small">After the deadline you would get 50% (${m(FX.half)}), never less. If we have to cancel, you get 100% back.</p></div>${actions(primary('Cancel order · refund '+m(FX.paid),'data-go="refund" data-v="requested"')+secondary('Keep my order','data-go="timeline" data-v="production"'))}</section>`
     :`<section class="co-card"><h2 class="co-h">Change or cancel</h2>${actions(secondary('Change your time','data-go="order-time-change" data-v="collection"')+secondary('Preview cancellation','data-go="timeline" data-v="cancel-production"'))}</section>`),
    orderSummary({}))}
  if(v==='delivery')return orderShell(status({tone:'success',title:'Your cake is being made',live:false,lines:['Your cakes and delivery are paid. The chef has confirmed your delivery and started making your cake.']})+
    lanes([['Cakes paid · '+m(FX.paid),'Tue 6 October, 14:05','done'],['Delivery paid · '+m(FX.delivery),'Fri 9 October, 09:30','done'],['Full refund until 11:00 on Sat 17 October','Covers cakes and delivery; from then on 50%','']],
     [confirmed,['Delivery confirmed by the chef',`${FX.postcode} · Thu 22 October, 11:00–12:00`,'done'],['Being made','The chef started on Thu 8 October','current'],['Out for delivery','On Thu 22 October',''],['Delivered','You receive it at your address','']])+
    `<section class="co-card"><h2 class="co-h">Change or cancel</h2><p>Need a different delivery time? Please <a href="contact.html">contact the chef</a>: a GK delivery time can only change with the chef’s agreement.</p>${actions(secondary('Preview cancellation','data-go="cancel" data-v="delivery"'))}</section>`,
    orderSummary({mode:'delivery',rows:[['Cakes',m(FX.paid)],['GK delivery',m(FX.delivery)],['Paid',m(FX.deliveryTotal),'total']]}));
  if(v==='no-show')return orderShell(status({tone:'warning',title:'Your cake wasn’t collected',lines:['Your cake was ready at St Katharine Docks on Thu 22 October, 11:00–12:00, but it wasn’t collected.',`Under the refund terms you get 50% of what you paid back: <strong>${m(FX.half)}</strong>.`,`Refund of ${m(FX.half)} requested. We’ll update this page as it progresses.`],after:actions(link('Contact the chef','contact.html'))})+
    lanes([paidRow,['Refund of '+m(FX.half)+' requested','50% for a cake that wasn’t collected','current'],['Returned to your payment method','','']],[confirmed,made,ready,['Not collected','The collection time passed on Thu 22 October','problem']]),
    orderSummary({rows:[['Cakes',m(FX.paid)],['Paid',m(FX.paid),'total'],['Refund due',m(FX.half)],['Returned so far','£0']]}));
  if(v==='completed'||v==='completed-refund'){const r=v==='completed-refund';
   return orderShell(status({tone:'success',title:'Your order is complete',lines:r?['Thank you for ordering with GK Cakes.',`Refund of ${m(FX.half)} requested. You arranged this with the chef after collection. We’ll update this page as it progresses.`]:['Thank you for ordering with GK Cakes.','Something wrong with your cake? Please contact the chef: they’ll look at it with you and can arrange a refund.'],after:r?'':actions(link('Contact the chef about your cake','contact.html'))})+
    lanes(r?[paidRow,['Refund of '+m(FX.half)+' requested','Arranged with the chef on Fri 23 October','current'],['Returned to your payment method','','']]:[paidRow],[confirmed,made,ready,['Collected','Thu 22 October, 11:20','done']]),
    orderSummary({rows:r?[['Cakes',m(FX.paid)],['Paid',m(FX.paid),'total'],['Refund due',m(FX.half)],['Returned so far','£0']]:undefined,note:r?'Your collection stays in the order history; the refund is shown separately.':''}))}
  return orderShell(status({tone:'warning',title:'We couldn’t deliver your cake today',lines:[`The delivery to ${FX.postcode} on Thu 22 October, 11:00–12:00 couldn’t be completed. The chef will contact you today to agree what happens next.`,`If it couldn’t be delivered because of a problem on our side, your delivery payment of <strong>${m(FX.delivery)}</strong> comes back in full.`],after:actions(link('Contact the chef','contact.html'))})+
    lanes([['Cakes paid · '+m(FX.paid),'Tue 6 October','done'],['Delivery paid · '+m(FX.delivery),'Fri 9 October','done'],['Delivery refund','Decided with the chef','']],[confirmed,['Delivery confirmed by the chef','','done'],made,['Out for delivery','Thu 22 October, 10:15','done'],['Delivery couldn’t be completed','Thu 22 October, 11:40 · the chef will contact you','problem']]),
    orderSummary({mode:'delivery',rows:[['Cakes',m(FX.paid)],['GK delivery',m(FX.delivery)],['Paid',m(FX.deliveryTotal),'total']]}))}});

def('time-list',{group:'r02 items',label:'Visible start–end times (radio list)',api:'GET /schedule rows {id, starts_at, ends_at, availability available|requestable|unavailable}. Loading, none and failure are distinct; Retry only for failure. Same picker as GK-016.',
 variants:[['loaded','Times shown'],['delivery','GK delivery · requestable'],['loading','Loading'],['none','No times'],['failed','Couldn’t load']],
 render:v=>{const sat=['12:30–13:30','13:00–14:00','13:30–14:30','14:00–15:00'];const del=v==='delivery';
  const body={loaded:timeList(sat,{selected:'13:00–14:00'}),delivery:timeList(sat,{delivery:true,legend:'Requested delivery time · subject to chef confirmation'})+`<p class="small quiet">The time you choose is a request until the chef confirms it.</p>`,
   loading:`<fieldset class="time-list" aria-busy="true"><legend>Collection time · London time</legend><div class="time-options">${timeLoading()}</div></fieldset>`,
   none:`<fieldset class="time-list"><legend>Collection time · London time</legend><div class="notice"><div><p>No times are available on Sat 24 October for collection. We haven’t changed your date.</p></div></div></fieldset>${actions(secondary('Choose another date','data-date')+link('Contact the chef','contact.html','text-link'))}`,
   failed:`<fieldset class="time-list"><legend>Collection time · London time</legend><div class="notice error"><div><p>We couldn’t load the times just now. Nothing was booked.</p></div></div></fieldset>${actions(secondary('Try again','data-go="time-list" data-v="loaded"'))}`}[v];
  return `<div class="wrap checkout-page r02-page">${title('Checkout','Section 1 only · the rest of the checkout is unchanged from r01.')}<div class="checkout-layout"><form novalidate><section class="co-card"><h2 class="co-h"><span class="co-num" aria-hidden="true">1</span>When and how</h2><div class="co-date"><span>${icon('calendar')} <strong>Sat, 24 October 2026</strong> · London time</span><button class="text-link" type="button" data-date>Change date</button></div><fieldset class="co-modes"><legend class="sr-only">How you will get your cake</legend>${[['collection','Collect · Free','St Katharine Docks, London.'],['courier','Your own courier','You book and pay your courier to collect at your time.'],['delivery','GK delivery · from £100','The chef quotes for your address. Delivery is paid separately.']].map(([val,h,s])=>`<label class="mode-card"><input type="radio" name="fulfilment" value="${val}" ${(del?'delivery':'collection')===val?'checked':''} data-go="time-list" data-v="${val==='delivery'?'delivery':'loaded'}"><span><strong>${h}</strong><small>${s}</small></span></label>`).join('')}</fieldset>${body}</section><p class="small quiet">Try it in context: <a href="checkout.html?seed=pink">the checkout</a> now uses this list (add a cake first).</p></form>
   <aside class="co-summary r02-notes" aria-labelledby="sum-title"><h2 id="sum-title">How the list behaves</h2><ul class="co-assure"><li>Times appear by themselves when the page opens and whenever the date, the handover option or the cakes change. No “Check” button.</li><li>Each time shows its start and end in London time. Arrow keys move between times; Space selects.</li><li>Your time is kept when it’s still available. If it isn’t, we say so and you choose again: we never pick one for you.</li><li>GK delivery shows the chef’s published times as requests, not bookings.</li><li>Loading, no times and a failed load look different. “Try again” appears only when loading failed.</li></ul></aside></div></div>`}});

def('order-time-change',{group:'r02 items',label:'Time changes: none for GK delivery',api:'POST /orders/{id}/pickup only for collection and own-courier orders: same day, ≥6 h before the current start. No customer self-change for GK delivery (K06).',
 variants:[['delivery','GK delivery order'],['collection','Collection order']],
 render:v=>{const del=v==='delivery';
  return orderShell(status({tone:'success',title:'Your order is confirmed',lines:['We’ve received your payment and your order is confirmed.'],live:false})+
   (del?`<section class="co-card"><h2 class="co-h">Change or cancel</h2><p>Need a different delivery time? Please <a href="contact.html">contact the chef</a>: a GK delivery time can only change with the chef’s agreement.</p>${actions(secondary('Preview cancellation','data-go="cancel" data-v="before"'))}</section>`:
   `<section class="co-card"><h2 class="co-h">Change your time</h2><p class="small">You can move to another time on the same day until ${FX.moveBy} (6 hours before your current time). For another date, please contact the chef.</p>${timeList(['11:00–12:00','12:00–13:00'],{selected:'11:00–12:00',legend:'Collection time on Thu 22 October · London time',name:'move',id:'move'})}${actions(secondary('Move to the selected time','data-move')+secondary('Preview cancellation','data-go="cancel" data-v="before"'))}<p class="small quiet">Moving your time doesn’t change your refund deadline.</p></section>`),
   orderSummary({mode:del?'delivery':'collection',rows:del?[['Cakes',m(FX.paid)],['GK delivery',m(FX.delivery)],['Paid',m(FX.deliveryTotal),'total']]:undefined}))}});

/* ---------- Design-review switcher (prototype only) ---------- */
const ids=Object.keys(S);
function review(id,v){const s=S[id],i=ids.indexOf(id),groups=[...new Set(ids.map(k=>S[k].group))];
  return `<aside class="r02-review" aria-label="Design review controls, prototype only"><p class="r02-review-tag">Prototype only · design review · not part of the shop</p><div class="r02-review-row"><label class="r02-review-pick">State <select id="r02-state">${groups.map(g=>`<optgroup label="${g}">${ids.filter(k=>S[k].group===g).map(k=>`<option value="${k}" ${k===id?'selected':''}>${S[k].label}</option>`).join('')}</optgroup>`).join('')}</select></label><a class="text-link" href="recovery.html?state=${ids[(i-1+ids.length)%ids.length]}">← Previous</a><a class="text-link" href="recovery.html?state=${ids[(i+1)%ids.length]}">Next →</a><a class="text-link" href="states.html">All states</a></div>${s.variants?`<nav class="r02-variants" aria-label="Variant">${s.variants.map(([k,l])=>`<a href="recovery.html?state=${id}&v=${k}" ${k===v?'aria-current="true"':''}>${l}</a>`).join('')}</nav>`:''}<p class="r02-review-api"><span>API</span> ${s.api}</p></aside>`}

function recoveryPage(){let id=q.get('state');if(!S[id])id='still-checking';const s=S[id];let v=q.get('v');if(s.variants&&!s.variants.some(x=>x[0]===v))v=s.variants[0][0];
  document.title=`${s.label} · GK-017 r02 · GK Cake London`;return review(id,v)+s.render(v)}
function statesPage(){const groups=[...new Set(ids.map(k=>S[k].group))];
  return `<div class="wrap r02-page">${title('GK-017 r02 · problem states','Design review index · prototype only. Each state opens with its design-review switcher.')}<div class="narrow r02-index">${groups.map(g=>`<section><h2>${g}</h2><ul>${ids.filter(k=>S[k].group===g).map(k=>`<li><a href="recovery.html?state=${k}">${S[k].label}</a>${S[k].variants?`<span class="small quiet"> · ${S[k].variants.map(([vk,l])=>`<a href="recovery.html?state=${k}&v=${vk}">${l}</a>`).join(' · ')}</span>`:''}</li>`).join('')}</ul></section>`).join('')}<section><h2>In the r01 pages</h2><ul><li><a href="checkout.html">Checkout</a> now uses the radio list of times (add a cake first, e.g. <a href="cake.html?id=pink">Pink piping</a>). Its design-review box also opens the r02 states.</li><li><a href="order.html?example=true&mode=delivery">Order page · GK delivery</a>: no time change. <a href="order.html?example=true">Collection</a>: “Preview time change” stays.</li></ul></section></div></div>`}

/* ---------- Behaviour ---------- */
function go(state,v){location.href=`recovery.html?state=${state}${v?'&v='+v:''}`}
function bind(){if(!['recovery','states'].includes(document.body.dataset.page))return;
  document.querySelector('#r02-state')?.addEventListener('change',e=>go(e.target.value));
  document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener(b.matches('input')?'change':'click',()=>go(b.dataset.go,b.dataset.v)));
  document.querySelectorAll('[data-restart]').forEach(b=>b.addEventListener('click',()=>{try{sessionStorage.setItem('gk-poc-gk017r02-bag',JSON.stringify(['pink']));sessionStorage.setItem('gk-poc-gk017r02-date',JSON.stringify(FX.date))}catch{}location.href='checkout.html'}));
  document.querySelectorAll('[data-keep]').forEach(b=>b.addEventListener('click',()=>go('order-time-change','collection')));
  document.querySelectorAll('[data-move]').forEach(b=>b.addEventListener('click',()=>{const st=document.querySelector('#move-status');const t=document.querySelector('input[name=move]:checked')?.value;st.textContent=t==='11:00–12:00'?'That’s your current time. Choose a different time to move.':`Preview only: your time would move to ${t}. Nothing was changed.`}));
  // Problem banners and status headings take focus so screen readers hear what changed.
  const f=['.r02-problem .r02-focus','.r02-cancel .r02-focus','.r02-status .r02-focus'].map(x=>document.querySelector(x)).find(Boolean);if(f&&document.body.dataset.page==='recovery'&&!q.has('shot'))f.focus({preventScroll:true});
  // Re-tick: Continue checks the tick-box and the time like the r01 checkout.
  const form=document.querySelector('#r02-form');form?.addEventListener('submit',e=>{e.preventDefault();const errs=[];const box=document.querySelector('#reviewed');const slot=document.querySelector('#slot');
    if(slot&&!slotValue(form)){document.querySelector('#slot-error').hidden=false;slot.setAttribute('aria-describedby','slot-status slot-error');errs.push(slot)}
    if(box&&!box.checked){box.setAttribute('aria-invalid','true');box.setAttribute('aria-describedby','reviewed-error');document.querySelector('#reviewed-error').hidden=false;errs.push(box)}
    if(errs.length){errs[0].focus();document.querySelector('#pay-status').textContent='Please check the highlighted item before paying.';return}
    const pay=document.querySelector('#r02-pay');pay.setAttribute('aria-busy','true');pay.classList.add('is-busy');document.querySelector('#pay-label').textContent=document.querySelector('#pay-label').textContent.includes('free')?'Placing your order…':'Opening secure payment…';document.querySelector('#pay-status').textContent='Opening secure payment…';
    setTimeout(()=>go(q.get('state')==='free'?'free':'confirming',q.get('state')==='free'?'confirm':''),700)});
  document.querySelector('#reviewed')?.addEventListener('change',e=>{e.target.removeAttribute('aria-invalid');document.querySelector('#reviewed-error').hidden=true});
  form?.addEventListener('change',e=>{if(e.target.name==='slot'){document.querySelector('#slot-error').hidden=true;const t=document.querySelector('#sum-time');if(t)t.textContent=e.target.value+' · London time';document.querySelector('#slot-status').textContent=`${e.target.value} chosen. Your refund deadline is updated below.`;const rt=document.querySelector('#refund-terms');if(rt){const d=DEADLINES[e.target.value];rt.outerHTML=terms(m(FX.paid),m(FX.half),true).replace(FX.deadline,d)}}});
  // Q5 alternatives: show collection/courier times only when relevant; confirm needs a choice.
  const choose=document.querySelector('#r02-choose');if(choose){choose.addEventListener('change',e=>{if(e.target.name==='alt'){document.querySelector('#alt-time').hidden=e.target.value==='refund';document.querySelector('#alt-error').hidden=true;const lg=document.querySelector('#alttime legend');if(lg)lg.textContent=(e.target.value==='courier'?'Courier collection time':'Collection time')+' on Thu 22 October · London time'}});
    choose.querySelector('[data-alt]').addEventListener('click',()=>{const a=choose.querySelector('input[name=alt]:checked')?.value;if(!a){const er=document.querySelector('#alt-error');er.hidden=false;choose.querySelector('input[name=alt]').focus();return}
      const paid=choose.dataset.paid==='1';if(a==='refund')return go('refund',paid?'q5-paid':'q5');if(!choose.querySelector('input[name=alttime]:checked')){document.querySelector('#alttime-error').hidden=false;choose.querySelector('input[name=alttime]').focus();return}go('delivery-impossible',a+(paid?'-paid':''))})}
  // Simulated polling: a quiet visible ticker; the live region only speaks when the state changes.
  document.querySelectorAll('[data-poll]').forEach(p=>{if(q.has('shot'))return;let n=3;const base=p.textContent;setInterval(()=>{n=n<=1?3:n-1;p.textContent=`${base} Checking again in ${n} s.`},1000)});
}
window.R02={pages:{recovery:recoveryPage,states:statesPage},bind};
})();
